      for (let y = y0; y <= y1; y += step) {
        const isMajor = Math.round(y / step) % 5 === 0;
        if (isMajor !== !!pass) continue;
        const sy = Math.round(oy - y * this.zoom) + 0.5;
        ctx.moveTo(0, sy);
        ctx.lineTo(w, sy);
      }
      ctx.stroke();
    }
