@import '@fontsource/lato/900.css';
@import '@fontsource/jetbrains-mono/400.css';
@import '@fontsource/jetbrains-mono/700.css';

/* Druk dwukolorowy: czerń i jedna zieleń na chłodnym, niepowlekanym papierze. */
:root {
  color-scheme: light;
  --paper: #f3f5f1;
  --sheet: #fbfcfa;
  --panel: #e8ebe5;
