/* Druk dwukolorowy: czerń i jedna zieleń na chłodnym, niepowlekanym papierze. */
:root {
  color-scheme: light;
  --paper: #f3f5f1;
  --sheet: #fbfcfa;
  --panel: #e8ebe5;
  --panel-2: #eef0eb;
  --rule: #d3d8d0;
