import { chromium } from 'playwright-core';
const { EXAMPLES } = await import('/work/src/examples');
const b = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
const out = '/work/.impeccable/review';
for (const [name, vp, dsf] of [['desktop', { width: 1440, height: 900 }, 1], ['mobile', { width: 390, height: 844 }, 2]] as const) {
  const ctx = await b.newContext({ viewport: vp, deviceScaleFactor: dsf });
  const p = await ctx.newPage();
  await p.goto('http://localhost:4173/');
  await p.waitForFunction(() => !!(window as any).logomocja);
  const ex = EXAMPLES.find((e) => e.id === 'drzewo')!;
  await p.evaluate(([s, m]) => (window as any).logomocja.open(s, m), [ex.source, ex.mode]);
  await p.evaluate(() => window.scrollTo(0, 0));
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${out}/${name}.png`, fullPage: true });
  for (const [route, file] of [['#/przyklady', 'gallery'], ['#/zadania/trzy-kwadraty', 'task'], ['#/pomoc/wyrazenia', 'help']]) {
    await p.evaluate((h) => (location.hash = h), route);
    await p.waitForTimeout(500);
    if (file !== 'help') await p.evaluate(() => window.scrollTo(0, 0));
    await p.screenshot({ path: `${out}/${name}-${file}.png`, fullPage: false });
  }
  await ctx.close();
}
await b.close();
EOF
